// Configuración de una aplicación que necesita la contraseña de su base de datos. Corrige su defecto principal.
export const configuracion = {
  aplicacion: "tienda-en-linea",
  secreto: {
    nombre: "tienda/base-de-datos",
    servicio: "AWS Secrets Manager",
    tipo: "credenciales de base de datos",
  },
  obtencion: "codigo-fuente",
  rotacion: { automatica: true },
};

solution.code:
export const configuracion = {
  aplicacion: "tienda-en-linea",
  secreto: {
    nombre: "tienda/base-de-datos",
    servicio: "AWS Secrets Manager",
    tipo: "credenciales de base de datos",
  },
  obtencion: "llamada-en-ejecucion",
  rotacion: { automatica: true },
};

spec.code:
assert.strictEqual(configuracion.secreto.servicio, "AWS Secrets Manager");
assert.strictEqual(configuracion.secreto.nombre, "tienda/base-de-datos");
assert.strictEqual(configuracion.secreto.tipo, "credenciales de base de datos");

exercises.starterCode:
// Política de la clave de AWS KMS que cifra los datos de los clientes. Corrige su defecto principal.
export const politicaDeClave = {
  clave: "datos-de-clientes",
  administradores: ["equipo-de-seguridad"],
  usuarios: ["aplicacion-de-pedidos", "aplicacion-de-facturas", "*"],
};

solution.code:
export const politicaDeClave = {
  clave: "datos-de-clientes",
  administradores: ["equipo-de-seguridad"],
  usuarios: ["aplicacion-de-pedidos", "aplicacion-de-facturas"],
};

spec.code:
for (const principal of [...politicaDeClave.administradores, ...politicaDeClave.usuarios]) {
  assert.ok(!principal.includes("*"), "el principal " + principal + " es un comodín");
}

const deConfianza = ["equipo-de-seguridad", "aplicacion-de-pedidos", "aplicacion-de-facturas"];
for (const principal of [...politicaDeClave.administradores, ...politicaDeClave.usuarios]) {
  assert.ok(deConfianza.includes(principal), principal + " no es de confianza");
}
